<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'admin' })
const route = useRoute(); const API_URL = 'http://localhost:8000'; const order = ref<any | null>(null); const loading = ref(true); const saving = ref(false)
onMounted(async () => { try { order.value = await $fetch<any>(`${API_URL}/orders/${route.params.id}`) } finally { loading.value = false } })
const updateStatus = async () => { if (!order.value) return; saving.value = true; try { order.value = await $fetch<any>(`${API_URL}/orders/${route.params.id}`, { method: 'PATCH', body: { status: order.value.status } }) } finally { saving.value = false } }
</script>
<template><section><div class="mb-8"><p class="text-[10px] font-bold uppercase tracking-[0.24em] text-primary">Manage</p><h1 class="mt-2 font-serif text-3xl font-bold tracking-tight text-ink sm:text-4xl">Order details</h1><p class="mt-2 text-sm text-gray-500">Review customer and item information.</p></div><div v-if="loading" class="py-20 text-center text-sm text-gray-500">Loading...</div><div v-else-if="order" class="grid max-w-5xl gap-6 lg:grid-cols-[1fr_320px]"><div class="rounded-2xl border border-[#d9e7e2] bg-white p-6 shadow-sm"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-[#e6efec] pb-5"><div><p class="text-xs font-bold uppercase tracking-[0.18em] text-primary">Order #{{ order.id }}</p><p class="mt-2 text-sm text-gray-500">{{ new Date(order.createdAt).toLocaleString() }}</p></div><select v-model="order.status" class="rounded-xl border border-gray-200 px-3 py-2 text-sm" @change="updateStatus"><option value="pending">Pending</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div><div class="divide-y divide-[#e6efec]"> <div v-for="item in order.items || []" :key="item.id" class="flex gap-4 py-4"><img :src="item.image" :alt="item.title" class="h-16 w-12 rounded-lg object-cover" /><div class="min-w-0 flex-1"><p class="font-semibold text-ink">{{ item.title }}</p><p class="mt-1 text-sm text-gray-500">Qty {{ item.quantity }} · ${{ Number(item.price).toFixed(2) }}</p></div></div></div></div><aside class="rounded-2xl border border-[#d9e7e2] bg-white p-6 shadow-sm"><h2 class="font-serif text-2xl font-bold text-ink">Customer</h2><p class="mt-5 font-semibold text-ink">{{ order.customerName }}</p><p class="mt-1 text-sm text-gray-500">{{ order.email }}</p><p class="mt-1 text-sm text-gray-500">{{ order.phone }}</p><p class="mt-5 text-sm leading-6 text-gray-600">{{ order.address }}, {{ order.city }} {{ order.postalCode }}</p><div class="mt-6 border-t border-[#e6efec] pt-5"><div class="flex justify-between text-sm text-gray-600"><span>Subtotal</span><span>${{ Number(order.subtotal || 0).toFixed(2) }}</span></div><div class="mt-2 flex justify-between text-sm text-gray-600"><span>Shipping</span><span>{{ Number(order.shipping || 0) ? '$' + Number(order.shipping).toFixed(2) : 'Free' }}</span></div><div class="mt-4 flex justify-between border-t border-[#e6efec] pt-4 font-bold text-ink"><span>Total</span><span>${{ Number(order.total || 0).toFixed(2) }}</span></div></div></aside></div></section></template>
